1: // DOCUMENTS: the Stage 6 trace machine — a DNS ask/answer prelude in front
2: // of the unchanged Stage 5 chain, plus the Stage 6b CDN branch keyed on the
3: // answer's subnet. Split from trace.js by responsibility (guard-file-size):
4: // trace.js stays the stages 1-5 machine verbatim and hands stage 6 to this
5: // module. Shared engine properties (clock callbacks, serve/finish routing)
6: // arrive in the constructor, so no shortcut is faked — the ask hop really
7: // runs the DNS ledger lookup, and the CDN hops really run the Router, the
8: // edge ledger, and the LB/backend pull.
9: //
10: // Hosted browser paths (<host>/<path>) split on the first slash: hop 1 is
11: // the ask to DNS 10.60, hop 2 is the ledger answer. A resolved target
12: // re-points the GET at the plain path, and a non-CDN (subnet-10) answer
13: // replays the Stage 5 chain byte-identically at hops 3-9 (s5 = hop - 1,
14: // minus the stage-5 emit hop so the wire frames stay real). Host-less paths
15: // (/<path>) run the Stage 5 shape exactly: 8 hops, same frames, no DNS
16: // consult. An NX answer renders the NX card on the browser and NO GET is
17: // emitted: the trace ends at hop 2 (CHECKS: pinned in
18: // test/sim/engine.test.js — a following traceHop restarts a fresh trace,
19: // it cannot walk a phantom hop 3).
20: //
21: // Stage 6b CDN branch (js/sim/cdn.js contract): when the DNS answer's
22: // subnet matches the edge's, the browser's GET rides the real Router into
23: // subnet 20 — hop 3 is a real `router.forward` crossing (`routed` +1); the
24: // wire token after the answer is the resolved mini-IP, not the hostname
25: // (the DL-4 rule holds here too). A GET inside the edge TTL is served from
26: // the fill ledger in 6 hops (edge HIT with the ledger's own bytes, the
27: // response's reverse crossing — `routed` +1 — then the render); a MISS
28: // pulls the origin through the Router in the 9-hop shape (real Router pull
29: // whose left-network delivery is the LB queueing it narrates, a real
30: // `drainUntilYou` so the origin's cache-aside status rides the frame, then
31: // the real `fill` + the reverse crossing + the render). A non-GET does
32: // not touch the edge ledger: it rides the MISS shape minus the fill (named
33: // counter-example pinned: edge counters stay at their initial values, the
34: // ledger row stays absent).
35: import { createCdnChain } from './cdn-chain.js';
36: import {
37:   drainUntilYou,
38:   backendFor,
39:   serveInto,
40:   finishTo,
41:   dbHopFrame,
42:   serveCacheSuffix,
43:   workerTailFrame,
44: } from './trace-helpers.js';
45: 
46: const subnetOf = (address) => String(address).split('.')[0];
47: 
48: export function createStage6Trace({
49:   serverAddress,
50:   servers,
51:   lb,
52:   dns,
53:   cdn = null,
54:   router = null,
55:   cache = null,
56:   database = null,
57:   workerQueue = null,
58:   bumpTick,
59:   getTick,
60:   onServe,
61:   onFinish,
62:   onDnsFail,
63: }) {
64:   if (!dns) {
65:     throw new Error('trace: stage 6 requires a DNS component');
66:   }
67:   if (!cdn) {
68:     throw new Error('trace: stage 6 requires the CDN edge component');
69:   }
70:   if (!router) {
71:     throw new Error('trace: stage 6 requires the Router component');
72:   }
73: 
74:   let trace = freshTrace(); // the live machine state, recreated per emission
75:   let served = null; // drained response held between the cache/db and serve hops
76:   let answer = null; // the DNS ledger result, held from the ask to the answer hop
77: 
78:   // The CDN hops live in their own module (guard-file-size split); it reads
79:   // and writes this machine's live trace object in place via getTrace.
80:   const cdnChain = createCdnChain({
81:     cdn,
82:     router,
83:     lb,
84:     servers,
85:     bumpTick,
86:     getTick,
87:     onServe,
88:     onFinish,
89:     getTrace: () => trace,
90:   });
91: 
92:   function freshTrace() {
93:     return {
94:       hop: 0,
95:       method: 'GET',
96:       path: '/about',
97:       host: null,
98:       dnsTarget: null,
99:       cdn: false,
100:       edgeStatus: null,
101:       nx: false,
102:       request: 'GET /about',
103:       targetServer: null,
104:       cacheStatus: null,
105:       dbOp: null,
106:       dbStale: false,
107:       asyncJob: false,
108:       response: null,
109:       status: null,
110:       body: null,
111:       routeId: null,
112:     };
113:   }
114: 
115:   // The Stage 5 chain, one stage-hop per call: s5 is the machine state the
116:   // original stage-5 conditions ran on, and the trace advances one hop per
117:   // call either way. Frames are assembled from the same trace fields, so
118:   // host-less output is identical to the stage-5 machine's.
119:   function chainStep(s5) {
120:     trace.hop += 1;
121:     if (s5 === 1) {
122:       return `routed ${trace.from} -> ${serverAddress} (${trace.request}) to LoadBalancer`;
123:     }
124:     if (s5 === 2) {
125:       const atTick = bumpTick();
126:       const target = lb.enqueue({
127:         id: `you:${atTick}`,
128:         from: trace.from,
129:         to: serverAddress,
130:         request: trace.request,
131:         atTick,
132:         isYou: true,
133:       });
134:       trace.targetServer = target;
135:       return `LB ${serverAddress} -> ${target} (${trace.request}) queued`;
136:     }
137:     if (s5 === 3) {
138:       const backend = backendFor(servers, trace.targetServer);
139:       served = drainUntilYou(backend, getTick);
140:       if (served) {
